const LG = { TX_DAYS: 14, NAMES_PROP: 'ESPN_NAMES', OVR_PROP: 'MY_OVERRIDES' };

// Noms des joueurs ESPN (id → nom), gardés d'une mise à jour à l'autre pour nommer les joueurs libérés
function espnNames_() {
