  const lg = gs ? fs / gs : 3.5, ids = {}, out = {};
  [1, 2, 3].forEach(k => { const d = data[pjPrev_(season, k)]; if (d) Object.keys(d.gk).forEach(id => { ids[id] = true; }); });
  Object.keys(ids).forEach(id => {
