// ---------------- Optimisation finale ----------------
const BT_FINAL = { w: [0.3, 0.4, 0.5, 0.6, 0.7, 0.8, 0.9, 1], gamma: [-0.4, -0.3, -0.2, -0.1, 0, 0.1, 0.2, 0.3, 0.4],
                   mult: [0.5, 0.75, 1, 1.5, 2], bias: [-0.3, -0.2, -0.15, -0.1, -0.05, 0, 0.05, 0.1, 0.15, 0.2, 0.3], MIN: 0.0005 };
