             retenu: gA > 0 && gB > 0 && Math.min(mA, mB) > -0.0005 && (gA + gB) / 2 >= MU.MIN_GAIN * 0.1 && Math.sign(cA[k] || 0) === Math.sign(cB[k] || 0) && (cA[k] || 0) !== 0 };
